arguments.command:
cd /app && cat > /tmp/extract.py <<'EOF'
import os, glob, fitz, pytesseract
from PIL import Image
docs=sorted(glob.glob('/app/documents/*'))
for d in docs:
    print("="*60); print(os.path.basename(d))
    try:
        if d.lower().endswith('.pdf'):
            doc=fitz.open(d); t="".join(p.get_text() for p in doc)
            if len(t.strip())<20:
                # render + ocr
                t=""
                for p in doc:
                    pix=p.get_pixmap(dpi=200)
                    img=Image.frombytes("RGB",[pix.width,pix.height],pix.samples)
                    t+=pytesseract.image_to_string(img)
            print(t)
        else:
            print(pytesseract.image_to_string(Image.open(d)))
    except Exception as e:
        print("ERR",e)
EOF
python3 /tmp/extract.py 2>/dev/null

